{"file_path":"sales_dashboard/loader.py","content":""""Load and prepare customer session data."""


def parse_session_log(lines):
    """Parse session-log lines according to SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day_text, converted_text = fields
        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc

        if converted_text == "1":
            converted = True
        elif converted_text == "0":
            converted = False
        elif converted_text == "":
            converted = None
        else:
            raise ValueError(f"line {line_number}: converted must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "converted": converted})
    return out


def dedupe_sessions(events):
    """Keep the last record for each id, sorted by day and then id."""
    by_id = {}
    for event in events:
        by_id[event["id"]] = event
    return sorted(by_id.values(), key=lambda event: (event["day"], event["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Count converted sessions for every day in the inclusive range."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["converted"] is True:
            counts[day - start_day] += 1
    return counts
"}

{"file_path":"sales_dashboard/report.py","content":""""Product analytics dashboard reporting helpers."""

from sales_dashboard.loader import daily_conversion_counts
from sales_dashboard.metrics import (
    conversion_rate,
    conversions_in_window,
    pooled_conversion_rate,
)


def campaign_summary(groups, days):
    """Summarize pooled conversion performance and recent conversions."""
    all_events = [event for events in groups.values() for event in events]
    if all_events:
        first_day = min(event["day"] for event in all_events)
        last_day = max(event["day"] for event in all_events)
        daily_counts = daily_conversion_counts(all_events, first_day, last_day)
        recent = conversions_in_window(daily_counts, days)
    else:
        recent = 0

    active_groups = sum(bool(events) for events in groups.values())
    return {
        "rate": round(pooled_conversion_rate(groups), 3),
        "recent": recent,
        "groups": active_groups,
    }


def top_converting_groups(groups, n):
    """Return the top non-empty groups by conversion rate, with name tie-breaks."""
    ranked = [
        (name, conversion_rate(events))
        for name, events in groups.items()
        if events
    ]
    ranked.sort(key=lambda item: (-item[1], item[0]))
    return [name for name, _rate in ranked[:n]]
